"use strict";
const $=s=>document.querySelector(s),ticket=location.hash.slice(1),installation=new URLSearchParams(location.search).get('installation');history.replaceState(null,'',location.pathname+location.search);let session,feedbackSession;
function add(text,kind){const p=document.createElement('p');p.textContent=text;p.className=kind||'';$('#messages').append(p);$('#messages').scrollTop=$('#messages').scrollHeight;return p}
async function call(path,data){const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),d=await r.json();if(!r.ok)throw Error(d.error||'Servizio non disponibile.');return d}
(async()=>{try{const d=await call('installation-session',{installation,ticket});session=d.session;feedbackSession=d.session;$('#name').textContent=d.name;add(d.greeting);$('#message').disabled=false;$('#chat button').disabled=false;window.dispatchEvent(new Event('linea-ready'))}catch(e){$('#status').textContent='Questa chat non è disponibile. Riaprila dal sito dell’azienda.'}})();
$('#chat').addEventListener('submit',async e=>{e.preventDefault();const message=$('#message').value.trim();if(!message||!session)return;add(message,'user');$('#message').value='';$('#chat button').disabled=true;$('#message').disabled=true;const waiting=add('');waiting.className='typing';waiting.setAttribute('aria-label','Risposta in preparazione');for(let i=0;i<3;i++){const dot=document.createElement('span');dot.textContent='•';waiting.append(dot)}try{const d=await call('chat',{session,message});add(d.reply);if(d.closed){session=null;$('#status').textContent='Conversazione conclusa. Grazie!'}}catch(err){$('#status').textContent=err.message}finally{waiting.remove();$('#message').disabled=!session;$('#chat button').disabled=!session}});

$('#feedback').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');if(!feedbackSession){$('#feedback-status').textContent='Apri prima una conversazione.';return}button.disabled=true;try{const f=new FormData(e.target);await call('feedback',{session:feedbackSession,rating:Number(f.get('rating')),comment:f.get('comment')});$('#feedback-status').textContent='Grazie per il tuo feedback.'}catch(err){$('#feedback-status').textContent=err.message;button.disabled=false}});

window.lineaAgentSession=async()=>{if(!session)throw Error('Apri una conversazione attiva.');return session};window.lineaAgentMessage=add;
